CREATE TABLE documents(module TEXT COLLATE __COLLATION__ NOT NULL,scope_kind TEXT COLLATE __COLLATION__ NOT NULL,scope_id TEXT COLLATE __COLLATION__ NOT NULL,collection TEXT COLLATE __COLLATION__ NOT NULL,key TEXT COLLATE __COLLATION__ NOT NULL,revision BIGINT NOT NULL CHECK(revision>0),version BIGINT NOT NULL,body TEXT NOT NULL,PRIMARY KEY(module,scope_kind,scope_id,collection,key));
CREATE TABLE document_indexes(module TEXT COLLATE __COLLATION__ NOT NULL,scope_kind TEXT COLLATE __COLLATION__ NOT NULL,scope_id TEXT COLLATE __COLLATION__ NOT NULL,collection TEXT COLLATE __COLLATION__ NOT NULL,key TEXT COLLATE __COLLATION__ NOT NULL,index_name TEXT COLLATE __COLLATION__ NOT NULL,eq_text TEXT COLLATE __COLLATION__ NOT NULL,sort_int BIGINT NOT NULL,sort_text TEXT COLLATE __COLLATION__ NOT NULL,PRIMARY KEY(module,scope_kind,scope_id,collection,key,index_name),FOREIGN KEY(module,scope_kind,scope_id,collection,key) REFERENCES documents(module,scope_kind,scope_id,collection,key) ON DELETE CASCADE);
CREATE INDEX lookup_index ON document_indexes(module,scope_kind,scope_id,collection,index_name,eq_text,sort_int,sort_text,key);
CREATE TABLE streams(module TEXT COLLATE __COLLATION__ NOT NULL,scope_kind TEXT COLLATE __COLLATION__ NOT NULL,scope_id TEXT COLLATE __COLLATION__ NOT NULL,stream TEXT COLLATE __COLLATION__ NOT NULL,next_seq BIGINT NOT NULL,PRIMARY KEY(module,scope_kind,scope_id,stream));
CREATE TABLE stream_records(module TEXT COLLATE __COLLATION__ NOT NULL,scope_kind TEXT COLLATE __COLLATION__ NOT NULL,scope_id TEXT COLLATE __COLLATION__ NOT NULL,stream TEXT COLLATE __COLLATION__ NOT NULL,seq BIGINT NOT NULL,kind TEXT COLLATE __COLLATION__ NOT NULL,created BIGINT NOT NULL,dedup TEXT COLLATE __COLLATION__ NOT NULL,body TEXT NOT NULL,PRIMARY KEY(module,scope_kind,scope_id,stream,seq),UNIQUE(module,scope_kind,scope_id,stream,dedup),FOREIGN KEY(module,scope_kind,scope_id,stream) REFERENCES streams(module,scope_kind,scope_id,stream));
CREATE TABLE migrations(module TEXT COLLATE __COLLATION__ NOT NULL,scope_kind TEXT COLLATE __COLLATION__ NOT NULL,scope_id TEXT COLLATE __COLLATION__ NOT NULL,collection TEXT COLLATE __COLLATION__ NOT NULL,target BIGINT NOT NULL,last_key TEXT COLLATE __COLLATION__ NOT NULL,PRIMARY KEY(module,scope_kind,scope_id,collection,target));

CREATE INDEX stream_kind_time ON stream_records(module,scope_kind,scope_id,stream,kind,created,seq);
